fn replace_last_element(first: &Vec<i32>, second: &Vec<i32>) -> Vec<i32> {
    // We assume `first` is non-empty, so `first.len() >= 1`.
    // Pre-allocate enough space for the prefix of `first` (excluding its last element)
    // plus all of `second`.
    let prefix_len = first.len() - 1;
    let mut replaced_list = Vec::with_capacity(prefix_len + second.len());

    // Copy all elements of `first` except its last one.
    replaced_list.extend_from_slice(&first[..prefix_len]);

    // Append all elements of `second`.
    replaced_list.extend_from_slice(&second[..]);

    replaced_list
}

